<script setup lang="ts">
import { computed, onMounted, onUnmounted, ref, watch } from 'vue';
import { Check, LoaderCircle, RefreshCw, Zap } from 'lucide-vue-next';
import { useApi, isCancelled, onSessionExpired, onAccessDenied } from '../lib/api';
import { operationID, stamp } from '../lib/commerce';
import { cryptoOperationsSupported, cryptoSetupDefaults, cryptoSetupSelection, confirmCryptoSetup, type CryptoSetupOperation, type CryptoSettings } from '../lib/cryptoPayments';
import { canAllocate, walletSupportsChain, type CryptoWallet } from '../lib/cryptoWallet';
import { t } from '../i18n';
import { usePaymentModule } from '../lib/paymentModule';
const props=withDefaults(defineProps<{wallets:CryptoWallet[];active?:boolean}>(),{active:true});
const {enabled:moduleEnabled}=usePaymentModule(()=>props.active);
const api=useApi('/commerce/crypto/admin'),settings=ref<CryptoSettings>(),loading=ref(false),busy=ref(false),error=ref(''),notice=ref(''),password=ref(''),setupPassword=ref(''),advanced=ref(false),savedEnabled=ref(false),statusKnown=ref(false);
const setupWalletID=ref(''),setupChainIDs=ref<number[]>([56]),setupAssetIDs=ref<string[]>(['bsc-usdt','bsc-usdc']);
const setupWallet=computed(()=>props.wallets.find(wallet=>wallet.id===setupWalletID.value));
const advancedWallet=computed(()=>props.wallets.find(wallet=>wallet.id===settings.value?.wallet_id));
const setupChains=computed(()=>settings.value?.chains.filter(chain=>cryptoOperationsSupported(chain.chain_id)&&walletSupportsChain(setupWallet.value,chain.chain_id))||[]);
const canSetup=computed(()=>!!settings.value&&moduleEnabled.value&&!!setupWallet.value&&canAllocate(setupWallet.value)&&setupChainIDs.value.length>0&&setupChainIDs.value.every(id=>setupAssetIDs.value.some(assetID=>settings.value?.assets.some(asset=>asset.id===assetID&&asset.chain_id===id))));
let disposed=false,sequence=0,pending:{key:string;id:string}|undefined;
const setupPending=ref<CryptoSetupOperation>();
function resetSetupSelection(){if(!settings.value)return;const value=cryptoSetupDefaults(setupWallet.value,settings.value);setupChainIDs.value=value.chain_ids;setupAssetIDs.value=value.asset_ids;setupPending.value=undefined;}
function chooseWallet(){setupPassword.value='';resetSetupSelection()}
function chooseChain(id:number,event:Event){const checked=(event.target as HTMLInputElement).checked;if(checked){setupChainIDs.value=[...new Set([...setupChainIDs.value,id])];const assets=settings.value?.assets.filter(asset=>asset.chain_id===id&&['USDT','USDC'].includes(asset.symbol)).map(asset=>asset.id)||[];setupAssetIDs.value=[...new Set([...setupAssetIDs.value,...assets])]}else{setupChainIDs.value=setupChainIDs.value.filter(chain=>chain!==id);setupAssetIDs.value=setupAssetIDs.value.filter(assetID=>settings.value?.assets.find(asset=>asset.id===assetID)?.chain_id!==id)}setupPending.value=undefined;}
function accept(value:CryptoSettings){statusKnown.value=true;savedEnabled.value=value.enabled;settings.value={...value,rate_mode:value.rate_mode||'manual'};if(!setupWalletID.value||!props.wallets.some(wallet=>wallet.id===setupWalletID.value))setupWalletID.value=value.wallet_id||props.wallets[0]?.id||'';resetSetupSelection()}
async function load(){if(!props.active)return;const current=++sequence;loading.value=true;error.value='';try{const value=await api<CryptoSettings>('/setup/status');if(!disposed&&current===sequence&&props.active)accept(value)}catch(reason){if(!disposed&&current===sequence&&!isCancelled(reason))error.value=t((reason as Error).message)}finally{if(current===sequence)loading.value=false}}
async function setup(){
 if(!settings.value||busy.value||!props.active)return;if(!moduleEnabled.value){error.value=t('支付模块已关闭，请先启用支付模块。');return}
 let value:ReturnType<typeof cryptoSetupSelection>;try{value=cryptoSetupSelection(setupWallet.value,settings.value,setupChainIDs.value,setupAssetIDs.value)}catch(reason){error.value=(reason as Error).message;return}
 busy.value=true;error.value='';notice.value='';const key=JSON.stringify(value);if(setupPending.value?.key!==key)setupPending.value={key,id:operationID(),completed:false};
 const operation=setupPending.value,current=++sequence;loading.value=false;statusKnown.value=false;
 try{const result=await confirmCryptoSetup(api,value,operation,setupPassword.value);if(!disposed&&props.active&&current===sequence){accept(result);notice.value=!result.enabled?t('启用请求已处理，当前收款已关闭，请核对最新设置。'):result.readiness?.ready?t('当前收款已启用，状态检查通过。'):t('启用请求已处理，当前收款仍需检查，请查看状态说明。')}}
 catch(reason){if(!disposed&&current===sequence&&!isCancelled(reason))error.value=operation.completed?t('启用请求已处理，但暂时无法确认当前状态。请刷新查看，勿重复提交。'):t((reason as Error).message)}finally{setupPassword.value='';busy.value=false}
}
async function save(){if(!settings.value||busy.value||!props.active)return;if(settings.value.enabled&&!moduleEnabled.value){error.value=t('支付模块已关闭，请先启用支付模块。');return}busy.value=true;error.value='';notice.value='';const value=JSON.parse(JSON.stringify(settings.value));delete value.readiness;const key=JSON.stringify(value);if(pending?.key!==key)pending={key,id:operationID()};try{const result=await api<CryptoSettings>('/settings','POST',{...value,password:password.value,operation_id:pending.id});if(!disposed&&props.active){accept(result);pending=undefined;notice.value=t('加密货币付款设置已保存')}}catch(reason){if(!disposed&&!isCancelled(reason))error.value=t((reason as Error).message)}finally{password.value='';busy.value=false}}
function changeAdvancedWallet(){if(!settings.value)return;for(const chain of settings.value.chains)if(!walletSupportsChain(advancedWallet.value,chain.chain_id))chain.enabled=false;for(const asset of settings.value.assets)if(!walletSupportsChain(advancedWallet.value,asset.chain_id))asset.enabled=false;}
const clear=()=>{password.value='';setupPassword.value='';savedEnabled.value=false;statusKnown.value=false;setupPending.value=undefined;pending=undefined;settings.value=undefined;sequence++};const unsub=onSessionExpired(clear),unsubAccess=onAccessDenied(clear);
watch(()=>props.wallets,()=>{if(!setupWallet.value&&settings.value){setupWalletID.value=props.wallets.find(wallet=>wallet.id===settings.value?.wallet_id)?.id||props.wallets[0]?.id||'';resetSetupSelection()}},{deep:true});
watch(advanced,()=>{password.value='';setupPassword.value=''});
watch(()=>props.active,active=>{password.value='';setupPassword.value='';if(active)void load();else sequence++});onMounted(()=>{void load()});onUnmounted(()=>{disposed=true;sequence++;password.value='';setupPassword.value='';unsub();unsubAccess()});
function dateInput(value:number){if(!value)return '';const date=new Date(value*1000);return new Date(date.getTime()-date.getTimezoneOffset()*60000).toISOString().slice(0,16)}
function setExpiry(id:string,event:Event){const asset=settings.value?.assets.find(item=>item.id===id);if(asset){const date=Date.parse((event.target as HTMLInputElement).value);asset.rate_expires_at=Number.isFinite(date)?Math.floor(date/1000):0}}
</script>
<template>
<section class="crypto-payment-settings" :aria-busy="busy||loading">
 <header class="crypto-config-heading"><div><h3><Zap :size="18"/>{{t('收款配置')}}</h3><p>{{t('选择钱包、网络与币种，系统自动检查连接并获取汇率。')}}</p></div><div class="crypto-config-actions"><span class="crypto-config-status" :class="{enabled:statusKnown&&savedEnabled}">{{!statusKnown?t('收款状态待确认'):savedEnabled?t('已开放加密货币付款'):t('未开放加密货币付款')}}</span><button type="button" :disabled="busy||loading" @click="load"><RefreshCw :size="15"/>{{t('刷新')}}</button></div></header>
 <p v-if="error" class="error" role="alert">{{error}}</p><p v-if="notice" class="crypto-config-success" role="status"><Check :size="17"/>{{notice}}</p><p v-if="loading&&!settings" role="status">{{t('加载中…')}}</p>
 <template v-if="settings">
  <form class="crypto-quick-setup" @submit.prevent="setup"><fieldset :disabled="busy||loading"><label>{{t('收款钱包')}}<select v-model="setupWalletID" required @change="chooseWallet"><option value="">{{t('请选择钱包')}}</option><option v-for="wallet in wallets" :key="wallet.id" :value="wallet.id">{{wallet.name}} · {{wallet.mode==='hot'?t('面板热钱包'):t('外部 xpub · 只读')}}</option></select></label>
   <p v-if="!wallets.length" class="crypto-config-note">{{t('先创建收款钱包，再下载并确认备份，即可一键启用。')}}</p><p v-else-if="setupWallet&&!canAllocate(setupWallet)" class="crypto-config-note">{{t('请先启用钱包并完成备份与恢复索引确认')}}</p>
   <div v-if="setupChains.length" class="crypto-setup-networks"><section v-for="chain in setupChains" :key="chain.id" class="crypto-setup-network" :class="{selected:setupChainIDs.includes(chain.chain_id)}"><label class="crypto-check"><input type="checkbox" :checked="setupChainIDs.includes(chain.chain_id)" @change="chooseChain(chain.chain_id,$event)"/><strong>{{chain.name}}</strong><span>{{chain.native_symbol}}</span></label><div v-if="setupChainIDs.includes(chain.chain_id)" class="crypto-setup-assets"><label v-for="asset in settings.assets.filter(item=>item.chain_id===chain.chain_id)" :key="asset.id" class="crypto-check"><input v-model="setupAssetIDs" type="checkbox" :value="asset.id" @change="setupPending=undefined"/><span>{{asset.symbol}}</span></label></div></section></div>
   <p class="crypto-config-note">{{t('启用前会检查主备连接、网络最终确认和自动报价；任何检查未通过都不会部分启用。')}}</p><p v-if="!moduleEnabled" class="crypto-config-note">{{t('支付模块已关闭，请先启用支付模块。')}}</p>
   <div class="crypto-setup-submit"><label>{{t('管理员当前密码')}}<input v-model="setupPassword" type="password" :required="!setupPending?.completed" autocomplete="current-password"/></label><button type="submit" class="primary" :disabled="!canSetup"><LoaderCircle v-if="busy" :size="16" class="spin"/><Zap v-else :size="16"/>{{busy?t('正在检查并启用…'):setupPending?.completed?t('确认最新状态'):t('一键启用收款')}}</button></div>
  </fieldset></form>
  <div v-if="statusKnown&&(settings.readiness||settings.rate_checked_at||settings.rate_error)" class="crypto-readiness" role="status"><p v-if="settings.readiness"><strong>{{settings.readiness.ready?t('收款准备就绪'):t('收款需要检查')}}</strong><span>{{t(settings.readiness.message)}}</span></p><p v-if="settings.rate_checked_at">{{t('汇率来源')}} · {{settings.rate_source||t('自动报价')}}<br/>{{t('最近更新')}} {{stamp(settings.rate_checked_at)}}</p><p v-if="settings.rate_error" class="error">{{t(settings.rate_error)}}</p></div>
  <details class="crypto-advanced" :open="advanced" @toggle="advanced=($event.target as HTMLDetailsElement).open"><summary>{{t('高级配置')}}<span>{{t('手动连接、汇率与停用设置')}}</span></summary><form @submit.prevent="save"><fieldset :disabled="busy||loading"><label class="crypto-check"><input v-model="settings.enabled" type="checkbox" :disabled="!moduleEnabled&&!settings.enabled"/>{{t('开放加密货币套餐付款')}}</label><div class="crypto-config-grid"><label>{{t('收款钱包')}}<select v-model="settings.wallet_id" :required="settings.enabled" @change="changeAdvancedWallet"><option value="">{{t('请选择钱包')}}</option><option v-for="wallet in wallets" :key="wallet.id" :value="wallet.id" :disabled="!canAllocate(wallet)">{{wallet.name}}{{canAllocate(wallet)?'':' · '+t('暂不可用')}}</option></select></label><label>{{t('付款报价有效期 / 分钟')}}<input v-model.number="settings.invoice_minutes" type="number" min="15" max="120" required/></label><label>{{t('汇率方式')}}<select v-model="settings.rate_mode" :aria-label="t('汇率方式')"><option value="automatic">{{t('自动获取汇率')}}</option><option value="manual">{{t('管理员手动设置')}}</option></select></label></div>
   <details v-for="chain in settings.chains.filter(item=>walletSupportsChain(advancedWallet,item.chain_id))" :key="chain.id" class="crypto-network-config"><summary>{{chain.name}} <span>{{chain.native_symbol}} · {{chain.enabled?t('已启用'):t('未启用')}}</span></summary><div class="crypto-config-grid"><label class="crypto-check"><input v-model="chain.enabled" type="checkbox" :disabled="!cryptoOperationsSupported(chain.chain_id)"/>{{t('允许此网络收款')}}</label><p class="crypto-config-note">{{t('连接来源')}} · {{chain.rpc_source==='built_in'?t('系统内置'):t('自定义')}}</p><p v-if="!cryptoOperationsSupported(chain.chain_id)" class="crypto-config-note">{{t('此网络尚未完成最终性验证，当前仅可查询余额。')}}</p><label>{{t('主 RPC 地址')}}<input v-model.trim="chain.rpc_url" type="url" autocomplete="off" :placeholder="chain.has_rpc?t('已配置，留空保持不变'):'https://…'"/></label><label>{{t('备用 RPC 地址')}}<input v-model.trim="chain.rpc_backup_url" type="url" autocomplete="off" :placeholder="chain.has_rpc_backup?t('已配置，留空保持不变'):'https://…'"/></label><p class="crypto-config-note wide">{{t('开启收款前，系统会检查两个 RPC 的网络与最终确认区块。RPC 中的密钥保存后不再回显。')}}</p></div><div v-for="asset in settings.assets.filter(item=>item.chain_id===chain.chain_id)" :key="asset.id" class="crypto-asset-config"><label class="crypto-check"><input v-model="asset.enabled" type="checkbox" :disabled="!cryptoOperationsSupported(chain.chain_id)"/>{{asset.symbol}} · {{asset.name}}</label><p class="crypto-contract">{{asset.contract}}</p><div class="crypto-config-grid"><template v-if="settings.rate_mode==='manual'"><label>{{t('手动汇率 / 元每枚')}}<input v-model.trim="asset.cny_per_token" inputmode="decimal" :required="asset.enabled"/></label><label>{{t('汇率有效至')}}<input :value="dateInput(asset.rate_expires_at)" type="datetime-local" :required="asset.enabled" @input="setExpiry(asset.id,$event)"/></label></template><p v-else class="crypto-config-note">{{t('自动报价')}} · {{asset.cny_per_token||'—'}} CNY / {{asset.symbol}}<br/>{{asset.rate_source||settings.rate_source||'—'}}</p><label>{{t('付款小数位数')}}<input v-model.number="asset.payment_decimals" type="number" min="0" :max="asset.decimals" required/></label><p class="crypto-config-note">{{t('最近更新')}} {{asset.rate_updated_at?stamp(asset.rate_updated_at):'—'}}</p></div></div></details>
   <p class="crypto-config-note">{{settings.rate_mode==='manual'?t('汇率由管理员手动设置，并非实时市场汇率。到期后停止创建新付款单，已有付款单保留原报价。'):t('自动汇率失效时暂停创建新付款单，已有付款单继续保留原报价。')}}</p><label>{{t('管理员当前密码')}}<input v-model="password" type="password" required autocomplete="current-password"/></label><button type="submit" class="primary"><LoaderCircle v-if="busy" :size="16" class="spin"/>{{busy?t('保存中…'):t('保存收款配置')}}</button></fieldset></form></details>
 </template>
</section>
</template>
<style scoped>
.crypto-payment-settings{border:1px solid var(--border);border-radius:12px;padding:18px;display:grid;gap:18px;font-size:13px;min-width:0}.crypto-config-heading{display:flex;align-items:flex-start;gap:14px;justify-content:space-between}.crypto-config-heading h3{display:flex;align-items:center;gap:8px;font-size:16px;margin:0 0 8px}.crypto-config-heading p{font-size:12px;line-height:1.8;color:var(--secondary);margin:0}.crypto-config-actions{display:flex;gap:10px;flex-wrap:wrap;justify-content:flex-end;flex-shrink:0}.crypto-config-status{font-size:12px;line-height:1.7;padding:5px 9px;background:var(--surface-raised);color:var(--secondary);border-radius:7px;align-self:center}.crypto-config-status.enabled{color:var(--accent-text);background:var(--accent-soft)}.crypto-payment-settings fieldset{border:0;padding:0;margin:0;display:grid;gap:18px;min-width:0}.crypto-payment-settings label{display:grid;gap:8px;margin:0;min-width:0;font-size:12px}.crypto-payment-settings label input,.crypto-payment-settings label select{width:100%;min-height:44px;min-width:0}.crypto-payment-settings .crypto-check{display:flex;flex-direction:row;align-items:center;gap:9px}.crypto-check input{width:17px!important;min-height:17px!important;flex-shrink:0;margin:0}.crypto-setup-networks{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,240px),1fr));gap:12px}.crypto-setup-network{padding:14px;border:1px solid var(--border);border-radius:10px;background:var(--surface-raised)}.crypto-setup-network.selected{border-color:var(--accent);background:var(--accent-soft)}.crypto-setup-network>.crypto-check>span{margin-left:auto;font-size:12px;color:var(--secondary)}.crypto-setup-assets{display:flex;gap:20px;padding:16px 0 0 26px;flex-wrap:wrap}.crypto-setup-submit{display:flex;gap:16px;align-items:flex-end;flex-wrap:wrap}.crypto-setup-submit>label{flex:1;min-width:180px}.crypto-payment-settings .primary{justify-self:start;min-height:44px}.crypto-config-grid{display:grid;grid-template-columns:1fr 1fr;gap:15px;min-width:0}.crypto-config-grid .wide{grid-column:1/-1}.crypto-advanced{padding-top:16px;border-top:1px solid var(--border);min-width:0}.crypto-advanced>summary{cursor:pointer;line-height:1.8;font-weight:600}.crypto-advanced>summary>span{display:block;font-size:12px;color:var(--secondary);font-weight:400;margin-left:15px}.crypto-advanced form{padding-top:20px}.crypto-network-config{padding:15px;border:1px solid var(--border);border-radius:10px;min-width:0}.crypto-network-config summary{cursor:pointer;line-height:1.8}.crypto-network-config summary span{font-size:12px;color:var(--secondary)}.crypto-network-config>.crypto-config-grid{margin-top:17px}.crypto-asset-config{padding-top:16px;margin-top:16px;border-top:1px solid var(--border)}.crypto-config-note,.crypto-contract{font-size:12px;color:var(--secondary);line-height:1.8;margin:0;overflow-wrap:anywhere}.crypto-contract{font-family:monospace;margin:9px 0 13px}.crypto-readiness{display:flex;gap:18px;flex-wrap:wrap;padding:12px 14px;background:var(--surface-raised);border-radius:9px;font-size:12px;line-height:1.8;color:var(--secondary)}.crypto-readiness p{margin:0;flex:1;min-width:180px}.crypto-readiness strong,.crypto-readiness span{display:block}.crypto-readiness strong{color:var(--text);font-weight:600}.crypto-config-success{display:flex;align-items:flex-start;gap:8px;color:var(--accent-text);font-size:13px;line-height:1.7;margin:0}.crypto-config-success svg{flex-shrink:0;margin-top:2px}@media(max-width:600px){.crypto-payment-settings{padding:14px}.crypto-config-grid{grid-template-columns:1fr}.crypto-config-heading{flex-direction:column}.crypto-config-actions{justify-content:flex-start}.crypto-network-config{padding:12px}.crypto-setup-submit{display:grid;grid-template-columns:1fr}.crypto-setup-submit .primary{width:100%;justify-content:center}.crypto-readiness p{min-width:0;flex-basis:100%}}
</style>
